-- Every invoice generated by the app (Generar XML = manual, Generar vía Excel = excel), with
-- its XML as evidence. The report matches them with uploads (cargas_rndc) by empresa +
-- invoice number to show which ones were never uploaded to the RNDC.
create table if not exists facturas_generadas (
  id serial primary key,
  perfil_id integer not null references perfiles(id) on delete cascade,
  usuario_id integer not null references users(id) on delete cascade,
  numero_factura text not null,
  origen text not null check (origen in ('manual', 'excel')),
  archivo text not null,
  remesas integer not null default 0,
  xml_gz bytea,
  created_at timestamptz not null default now()
);

create index if not exists facturas_generadas_perfil_numero_idx on facturas_generadas (perfil_id, numero_factura);
create index if not exists cargas_rndc_perfil_numero_idx on cargas_rndc (perfil_id, numero_factura);

alter table facturas_generadas enable row level security;
